-- คอมไพล์ task_6451c19231b14139ab3d99b35ac9c734_020000_overwrite_ss_esim_checkpoint_temp.sql กับฐานจริงแบบไม่ดึงข้อมูล (WHERE 1=0) · SELECT อย่างเดียว
SELECT * FROM (
select partition_date, case when rnk in(1, 2) or checkpoint_partition <=(nth_value(checkpoint_partition, 2) over( order by checkpoint_partition)) + 300 then checkpoint_partition else min(checkpoint_partition) over (partition by partition_date) end as checkpoint_partition , process_date FROM ( SELECT CAST(TO_CHAR(process_date, 'YYYYMMDD') AS NUMBER) AS partition_date, checkpoint_partition, DENSE_RANK() OVER ( ORDER BY checkpoint_partition ASC) as rnk, process_date FROM ( SELECT DISTINCT partition_minute AS checkpoint_partition , SYSDATE AS process_date FROM DSSDEV.tb_landing_ss_esim WHERE partition_minute < TO_NUMBER(TO_CHAR(SYSDATE-INTERVAL '5' MINUTE, 'YYYYMMDDHH24MI')) AND partition_minute >= ( SELECT COALESCE(MAX(checkpoint_partition), 0) AS checkpoint_partition FROM DSSDEV.tb_staging_ss_esim_checkpoint) AND 'TRUE' = UPPER(COALESCE(( SELECT success FROM DSSDEV.tb_staging_ss_esim_landing_to_discovery_workflow_status), 'TRUE'))))
) WHERE 1=0
